from sdata1 import talk,svg,person,F,SUN,HILL,TEMPLE,B
D=dict
R='śrīveṅkaṭācalapate'
def L(a,b,c,d,n,tail=None):
    t=tail or [R,f'tava suprabhātam ‖{n}‖']
    return [a,b,c,t]
DOOR='<rect x="150" y="40" width="60" height="100" fill="#ffd60a" stroke="#111" stroke-width="3"/><path d="M180 40 v100" stroke="#111"/>'
def crowd(cols,x0=20,dx=22,y=132,s=.5): return ''.join(person(x0+dx*k,y,c,'#f2c79b',s) for k,c in enumerate(cols))
def lab(x,y,t,s=9): return f'<text x="{x}" y="{y}" text-anchor="middle" {F} font-size="{s}">{t}</text>'
V=[
D(n='16',lines=L(['sevāparāśśivasureśa-','kṛśānudharma-'],['rakṣo\'mbunāthapavamāna-','dhanādhināthāḥ |'],['baddhāñjalipravilasan-','nijaśīrṣadeśāḥ'],None,16),theme='THE GUARDIANS OF THE DIRECTIONS',
 svg=svg('Eight guardian gods of the directions standing with folded hands above their heads before a golden door',DOOR+crowd(['#bcd4f0','#ffd60a','#e63946','#333','#7a2a2a','#1d6fb8','#9fd3f0','#2a9d6f'],12,17,132,.42)+lab(70,30,'AṢṬA-DIKPĀLAKAS'),B),
 mean='Eager to serve, Śiva, Indra, Agni, Yama, Nirṛti, Varuṇa, Vāyu and Kubera, the lord of wealth, stand with hands folded and raised above their heads. O Lord of Veṅkaṭācala, good morning!',
 plain='The guardian gods of all eight directions wait at Your door with folded hands raised over their heads, ready to serve. Good morning, Lord!',
 words=[('sevā-parāḥ','<b>devoted to service</b>'),('sureśa · kṛśānu','<b>Indra</b> · <b>Agni</b>'),('dharma · rakṣas','<b>Yama</b> · <b>Nirṛti</b>'),('ambunātha · pavamāna','<b>Varuṇa</b> · <b>Vāyu</b>'),('dhana-adhinātha','<b>Kubera</b>, lord of wealth'),('baddha-añjali','<b>with folded hands</b>')],
 deep='<p><b>The eight guardians.</b> Hindu cosmology places a guardian (<i>dikpāla</i>) at each of the eight directions: Indra in the east, Agni south-east, Yama south, Nirṛti south-west, Varuṇa west, Vāyu north-west, Kubera north, and Īśāna (a form of Śiva) north-east. The verse names all eight.</p><p><b>Rulers turned servants.</b> These are the gods who rule the universe, but at this door they are <i>sevā-parāḥ</i>, servants. Their hands joined above their heads show the deepest respect.</p><p><b>Temple plan.</b> Many South Indian temples place the dikpālas around the shrine: the Lord is at the centre of every direction.</p>',
 cards=('💡 Dikpāla','"Guardian of a direction": eight gods for eight quarters.','💡 Añjali','Joined palms: the gesture of greeting and reverence.'),
 inner='Whatever power you hold in the world, at His door you are a servant.',
 talk=('Śiva in a Viṣṇu hymn?','Here as Īśāna, guardian of the north-east. All the directions\' rulers wait at the door with folded hands.'),
 key='The guardians of all eight directions <b>wait to serve Him</b>.',
 note='Some texts read sevāparāḥ śiva… (without sandhi) and rakṣombunātha.'),
D(n='17',lines=L(['dhāṭīṣu te vihagarāja-','mṛgādhirāja-'],['nāgādhirājagajarāja-','hayādhirājāḥ |'],['svasvādhikāramahimādhikam','arthayante'],None,17),theme='THE KINGS OF EVERY KIND',
 svg=svg('A procession with Garuda the eagle, a lion, a many-headed serpent, a white elephant and a white horse, each asking to carry the Lord',
  '<g stroke="#111" stroke-width="2"><path d="M20 70 l20 -20 l20 20 l-20 -6z" fill="#e63946"/><circle cx="80" cy="64" r="12" fill="#e0a800"/><path d="M110 76 q8 -30 16 0 q8 -30 16 0" fill="#2a7a4a"/><ellipse cx="60" cy="126" rx="26" ry="16" fill="#ddd"/><path d="M36 126 q-8 14 -2 22" fill="none"/><path d="M150 120 q20 -20 40 0 v20 h-40z" fill="#fff"/></g>'+lab(40,92,'GARUḌA',8)+lab(80,92,'SIṂHA',8)+lab(126,92,'ŚEṢA',8)+lab(60,154,'GAJA',8)+lab(170,154,'AŚVA',8)+lab(110,24,'VĀHANA SEVĀ',11),B),
 mean='In Your processions, Garuḍa the king of birds, the lion, king of beasts, Śeṣa, king of serpents, the king of elephants and the king of horses each ask for a greater share of glory in his own duty. O Lord of Veṅkaṭācala, good morning!',
 plain='In Your processions the king of birds, the lion, the great serpent, the royal elephant and the royal horse each ask to serve You better. Good morning, Lord!',
 words=[('dhāṭīṣu','<b>in processions</b>, outings'),('vihaga-rāja','<b>king of birds</b>: Garuḍa'),('mṛga-adhirāja','<b>king of beasts</b>: the lion'),('nāga-adhirāja','<b>king of serpents</b>: Śeṣa'),('gaja · haya','<b>elephant</b> · <b>horse</b>'),('sva-sva-adhikāra','<b>each his own duty</b>')],
 deep='<p><b>The vehicles.</b> When the Lord goes out in procession, He rides a <b>vāhana</b>, a vehicle. Garuḍa, the lion, Śeṣa, the elephant and the horse are all among the vāhanas on which the Lord is carried round the temple streets during festivals.</p><p><b>Competing to serve.</b> Each "king" asks for more glory in his own job: who will carry the Lord best? It is rivalry turned into devotion.</p><p><b>Each its place.</b> <i>Sva-sva-adhikāra</i>, "each his own role": none wants another\'s job, only to do his own better.</p>',
 cards=('💡 Vāhana','The vehicle or mount of a god; also the carriers used in temple processions.','💡 Garuḍa','The eagle king, Viṣṇu\'s mount; His banner too (verse 2).'),
 inner='Don\'t ask for someone else\'s role. Ask to do your own better.',
 talk=('The animals are asking for something?','To carry Him! Each one wants more glory in its own service. Rivalry, but the good kind.'),
 key='Bird, lion, serpent, elephant, horse: <b>each wants to carry Him</b>.',
 note='Some texts read mahimādikam for mahimādhikam.'),
D(n='18',lines=L(['sūryendubhaumabudha-','vākpatikāvyasauri-'],['svarbhānuketudiviṣat-','pariṣatpradhānāḥ |'],['tvaddāsadāsacaramāvadhi-','dāsadāsāḥ'],None,18),theme='THE NINE PLANETS AS SERVANTS',
 svg=svg('Nine planets in a circle bowing toward a temple at the centre',TEMPLE(110,96,.9)+''.join(f'<circle cx="{110+70*__import__("math").cos(k*0.698):.0f}" cy="{86+52*__import__("math").sin(k*0.698):.0f}" r="9" fill="{c}" stroke="#111" stroke-width="2"/>' for k,c in enumerate(['#ffd60a','#eee','#e63946','#2a9d6f','#ff8c1a','#fff','#333','#555','#8a6a4a']))+lab(110,154,'NAVAGRAHA',10),B),
 mean='The Sun, Moon, Mars, Mercury, Jupiter, Venus, Saturn, Rāhu and Ketu, leaders of the assembly of gods, are servants of the servants of Your servants, to the very last degree. O Lord of Veṅkaṭācala, good morning!',
 plain='Even the nine planets that rule our horoscopes are servants of Your servants\' servants. Good morning, Lord!',
 words=[('sūrya · indu','<b>Sun</b> · <b>Moon</b>'),('bhauma · budha','<b>Mars</b> · <b>Mercury</b>'),('vākpati · kāvya','<b>Jupiter</b> · <b>Venus</b>'),('sauri','<b>Saturn</b>'),('svarbhānu · ketu','<b>Rāhu</b> · <b>Ketu</b>'),('carama-avadhi','<b>to the last limit</b>')],
 deep='<p><b>The navagrahas.</b> The nine "graha" of Indian astrology: Sun, Moon, Mars, Mercury, Jupiter, Venus, Saturn, and the shadow points Rāhu and Ketu.</p><p><b>A comforting thought.</b> Many people fear the planets\' influence. The poet says they are only servants of the Lord\'s servants, "to the last degree": the devotee need not fear them.</p><p><b>Dāsa-dāsa.</b> "Servant of servants" is the Śrīvaiṣṇava ideal: to serve those who serve the Lord. Here the planets themselves take that humble place.</p>',
 cards=('💡 Navagraha','The nine planetary deities, often found in a shrine of their own in temples.','💡 Dāsa','Servant: the Śrīvaiṣṇava devotee calls himself "dāsa" or "adiyēn".'),
 inner='The planets serve His servants. Hold on to Him, and the stars are on your side.',
 talk=('So the planets can\'t trouble devotees?','That\'s the poet\'s comfort: they are servants of His servants\' servants. The Lord is above every star.'),
 key='The nine planets are <b>servants of His servants\' servants</b>.'),
D(n='19',lines=L(['tvatpādadhūlibharita-','sphuritottamāṅgāḥ'],['svargāpavarganirapekṣa-','nijāntaraṅgāḥ |'],['kalpāgamākalanayā-','kulatāṃ labhante'],None,19),theme='DEVOTEES WHO WANT NOTHING ELSE',
 svg=svg('Devotees with dust of the Lord\'s feet on their heads, turning away from a heaven on clouds and a door of liberation',
  '<path d="M150 50 q10 -20 30 -10 q20 -10 30 10 q10 20 -10 20 h-40 q-20 0 -10 -20z" fill="#fff" stroke="#111" stroke-width="2"/>'+lab(180,60,'SVARGA',8)+crowd(['#ff8c1a','#1d6fb8','#e63946'],40,30,132,.6)+''.join(f'<circle cx="{40+30*k}" cy="{98}" r="4" fill="#c9a26b"/>' for k in range(3))+'<path d="M24 30 c0 -10 20 -10 20 0 c0 10 -20 10 -20 0" fill="#f2c79b" stroke="#111"/>'+lab(110,24,'JUST HIS FEET',10),B),
 mean='Their heads shining with the dust of Your feet, their hearts caring nothing for heaven or liberation, they grow anxious at the thought of the end of the aeon. O Lord of Veṅkaṭācala, good morning!',
 plain='Your devotees, heads covered in the dust of Your feet, want neither heaven nor liberation; they only worry that the age might end and their service with it. Good morning, Lord!',
 words=[('pāda-dhūli','<b>dust of the feet</b>'),('uttama-aṅga','the <b>head</b> ("best limb")'),('svarga · apavarga','<b>heaven</b> · <b>liberation</b>'),('nirapekṣa','<b>indifferent to</b>'),('kalpa-agama','<b>the end of the aeon</b>'),('ākulatā','<b>anxiety</b>')],
 deep='<p><b>Not heaven, not mokṣa.</b> These devotees want neither heaven nor liberation. What they want is to go on serving the Lord at His feet. This is the highest bhakti in the Śrīvaiṣṇava view: service for its own sake.</p><p><b>Their one fear.</b> They worry only that the <i>kalpa</i>, the cosmic age, will end, and with it their chance to serve here.</p><p><b>The dust of His feet.</b> To carry the dust of the Lord\'s feet on your head is the humblest honour.</p>',
 cards=('💡 Kalpa','A "day of Brahmā": an aeon of 4.32 billion years, after which the worlds dissolve.','💡 Kaiṅkarya','Loving service to the Lord: the Śrīvaiṣṇava\'s highest goal.'),
 inner='The truest devotee asks for nothing but the chance to keep serving.',
 talk=('They don\'t even want mokṣa?','Not if it means leaving His feet. Their only worry is that this age of service might end!'),
 key='Not heaven, not liberation: <b>only the dust of His feet</b>.'),
D(n='20',lines=L(['tvadgopurāgraśikharāṇi','nirīkṣamāṇāḥ'],['svargāpavargapadavīṃ','paramāṃ śrayantaḥ |'],['martyā manuṣyabhuvane','matimāśrayante'],None,20),theme='ONE LOOK AT THE TOWER',
 svg=svg('People looking up at a golden temple tower shining on a hill, choosing to stay on earth',HILL+'<g stroke="#111" stroke-width="2.5"><rect x="140" y="50" width="40" height="40" fill="#ffd60a"/><path d="M134 50 l26 -30 l26 30z" fill="#e0a800"/></g>'+crowd(['#ff8c1a','#1d6fb8','#e05a8a'],30,26,140,.55)+lab(60,30,'ĀNANDA NILAYAM',9),B),
 mean='Gazing at the tops of Your towers, mortals feel they have reached the highest road to heaven and liberation, and set their hearts on staying in the world of men. O Lord of Veṅkaṭācala, good morning!',
 plain='Just seeing the golden tower over Your shrine, people feel they already have heaven and liberation, and are happy to stay on earth. Good morning, Lord!',
 words=[('gopura-agra-śikhara','the <b>peaks of the towers</b>'),('nirīkṣamāṇāḥ','<b>gazing at</b>'),('padavīm paramām','<b>the highest path</b>'),('martyāḥ','<b>mortals</b>'),('manuṣya-bhuvane','<b>in the human world</b>'),('matim āśrayante','<b>set their minds on</b>')],
 deep='<p><b>Earth over heaven.</b> A striking idea: once you have seen the Lord\'s temple, earth itself becomes better than heaven, because the Lord is here.</p><p><b>The golden tower.</b> The sanctum at Tirumala is crowned by the gilded <b>Ānanda Nilaya</b> vimāna, "abode of bliss", visible from far off.</p><p><b>Follows verse 19.</b> The devotees there wanted no heaven; here ordinary people, just from seeing the tower, feel the same.</p>',
 cards=('💡 Gopuram · vimāna','The gateway tower and the tower over the sanctum of a temple.','💡 Ānanda Nilaya','"Abode of bliss": the gilded vimāna over the Lord at Tirumala.'),
 inner='Where the Lord is near, earth is better than heaven.',
 talk=('People prefer earth to heaven?','After seeing His tower, yes! Why go anywhere when the Lord is right here?'),
 key='One look at His tower makes <b>earth better than heaven</b>.'),
D(n='21',lines=L(['śrībhūmināyaka','dayādiguṇāmṛtābdhe'],['devādhideva','jagadekaśaraṇyamūrte |'],['śrīmannananta','garuḍādibhirarcitāṅghre'],None,21),theme='LORD OF ŚRĪ AND BHŪ',
 svg=svg('The Lord standing between two goddesses, Sri and Bhu, with Garuda kneeling at his feet',
  '<g stroke="#111" stroke-width="2.5"><circle cx="110" cy="50" r="14" fill="#4a7fd0"/><path d="M96 34 h28 v-14 h-28z" fill="#ffd60a"/><path d="M86 140 q-4 -60 24 -76 q28 16 24 76z" fill="#ffd60a"/></g>'+person(50,140,'#e05a8a','#f2c79b',.65)+person(170,140,'#2a9d6f','#f2c79b',.65)+'<path d="M96 150 l14 -14 l14 14z" fill="#e63946" stroke="#111"/>'+lab(50,158,'ŚRĪ',9)+lab(170,158,'BHŪ',9),B),
 mean='O Lord of Śrī and Bhū, ocean of the nectar of compassion and every good quality; God of gods, the one refuge of the world; glorious Ananta, whose feet are worshipped by Garuḍa and others. O Lord of Veṅkaṭācala, good morning!',
 plain='Husband of Lakṣmī and of Mother Earth, ocean of kindness, God of gods, the world\'s only refuge, whose feet Garuḍa worships: good morning, Lord!',
 words=[('śrī-bhūmi-nāyaka','<b>Lord of Śrī and Bhū</b>'),('dayā-ādi-guṇa','<b>compassion and other virtues</b>'),('amṛta-abdhe','<b>ocean of nectar</b>'),('deva-adhideva','<b>God of gods</b>'),('eka-śaraṇya','<b>the one refuge</b>'),('arcita-aṅghre','<b>whose feet are worshipped</b>')],
 deep='<p><b>The Lord addressed directly.</b> Verses 21–24 drop description and simply call the Lord by His names and qualities: a garland of address.</p><p><b>Śrī and Bhū.</b> Viṣṇu has two principal consorts: Śrī (Lakṣmī, fortune) and Bhū (the Earth). In temple images they stand on either side of Him.</p><p><b>Śaraṇya.</b> "The one to take refuge in": the root of Śaraṇāgati, surrender, which the Prapatti section (Part 4) is all about.</p>',
 cards=('💡 Bhū Devī','Mother Earth as Viṣṇu\'s consort, rescued by Him as Varāha.','💡 Śaraṇāgati','Surrender to the Lord: the heart of Śrīvaiṣṇava practice.'),
 inner='Call Him by His qualities: compassion first.',
 talk=('Who is Bhū?','Mother Earth, Viṣṇu\'s second consort. Śrī is fortune, Bhū is the ground we stand on; both are His.'),
 key='Lord of Śrī and Bhū, <b>the one refuge of the world</b>.'),
D(n='22',lines=L(['śrīpadmanābha puruṣottama','vāsudeva'],['vaikuṇṭha mādhava','janārdana cakrapāṇe |'],['śrīvatsacihna','śaraṇāgatapārijāta'],None,22),theme='A GARLAND OF NAMES',
 svg=svg('A garland of flowers with names of Vishnu on each flower, around a discus',
  '<circle cx="110" cy="86" r="22" fill="#ffd60a" stroke="#111" stroke-width="3"/>'+''.join(f'<path d="M110 86 l{20*__import__("math").cos(k*0.785):.0f} {20*__import__("math").sin(k*0.785):.0f}" stroke="#111" stroke-width="2"/>' for k in range(8))+''.join(f'<circle cx="{110+66*__import__("math").cos(k*0.785):.0f}" cy="{86+56*__import__("math").sin(k*0.785):.0f}" r="9" fill="#f08aa6" stroke="#111"/>' for k in range(8))+lab(110,156,'PADMANĀBHA · MĀDHAVA · JANĀRDANA',8),B),
 mean='O Padmanābha, Puruṣottama, Vāsudeva, Vaikuṇṭha, Mādhava, Janārdana, holder of the discus; O One marked with Śrīvatsa, wish-granting tree for those who surrender. O Lord of Veṅkaṭācala, good morning!',
 plain='Lotus-navelled, Supreme Person, Vāsudeva, Lord of Vaikuṇṭha, Mādhava, Janārdana, discus-holder, wish-tree for those who surrender: good morning, Lord!',
 words=[('padma-nābha','<b>lotus-navelled</b>'),('puruṣa-uttama','<b>the Supreme Person</b>'),('mādhava','<b>husband of Mā</b> (Lakṣmī)'),('janārdana','<b>who moves people</b> / destroys evil'),('cakra-pāṇe','<b>discus in hand</b>'),('pārijāta','the <b>wish-granting tree</b>')],
 deep='<p><b>Names as prayer.</b> Each name is a small theology. Padmanābha: Brahmā is born from the lotus at His navel. Puruṣottama: higher than all beings (Gītā 15). Vāsudeva: He who dwells in all. Vaikuṇṭha: Lord of the world without sorrow.</p><p><b>Śrīvatsa.</b> The curl-mark on His chest where Lakṣmī lives (verse 13).</p><p><b>Pārijāta.</b> The heavenly tree that grants any wish: the Lord is that tree for those who surrender. Several of these names are among the twelve names of Viṣṇu chanted in daily worship.</p>',
 cards=('💡 Puruṣottama','"Highest Person": explained in Bhagavad Gītā chapter 15.','💡 Pārijāta','The heavenly wish-tree that came out of the churning of the ocean.'),
 inner='Each name of the Lord is a door. Any one will do.',
 talk=('So many names in one verse!','Each one is a little teaching: the lotus at His navel, the discus in His hand, the wish-tree for those who come to Him.'),
 key='Padmanābha, Vāsudeva, Mādhava: <b>a garland of His names</b>.'),
D(n='23',lines=L(['kandarpadarpahara-','sundaradivyamūrte'],['kāntākucāmburuha-','kuḍmalaloladṛṣṭe |'],['kalyāṇanirmalaguṇākara-','divyakīrte'],None,23),theme='MORE BEAUTIFUL THAN KĀMA',
 svg=svg('The god of love Kama with his flower bow lowering it in shame before the beautiful form of the Lord',
  '<g stroke="#111" stroke-width="2.5"><circle cx="150" cy="50" r="14" fill="#4a7fd0"/><path d="M136 34 h28 v-14 h-28z" fill="#ffd60a"/><path d="M126 140 q-4 -60 24 -76 q28 16 24 76z" fill="#ffd60a"/></g>'+person(60,140,'#e05a8a','#f2c79b',.65)+'<path d="M30 90 q10 -30 0 -50" fill="none" stroke="#2a9d6f" stroke-width="3"/>'+lab(60,158,'KĀMA',9)+lab(150,158,'SUNDARA',9),B),
 mean='O One whose beautiful divine form humbles the pride of Kāma, the god of love; whose loving gaze rests on His beloved Lakṣmī; O mine of pure, auspicious qualities, of divine fame. O Lord of Veṅkaṭācala, good morning!',
 plain='Your beauty puts even the god of love to shame; Your eyes rest lovingly on Lakṣmī; You are full of every pure and good quality. Good morning, Lord!',
 words=[('kandarpa','<b>Kāma</b>, the god of love'),('darpa-hara','<b>who removes the pride of</b>'),('kāntā','His <b>beloved</b> (Lakṣmī)'),('lola-dṛṣṭe','<b>whose gaze lingers</b>'),('kalyāṇa-guṇa-ākara','<b>mine of auspicious qualities</b>'),('divya-kīrte','<b>of divine fame</b>')],
 deep='<p><b>Beauty that humbles love.</b> Kāma is the most beautiful of the gods, yet the Lord\'s form takes away his pride. The Lord\'s beauty is not only of the body: the next line calls Him a mine of good qualities.</p><p><b>Love for Lakṣmī.</b> The poet pictures the Lord gazing lovingly at Lakṣmī, in the frank imagery of classical Sanskrit poetry. Divine love between Lord and Goddess is a model of devotion.</p><p><b>Kalyāṇa-guṇa.</b> "Auspicious qualities": in Rāmānuja\'s teaching, the Lord is full of every good quality and free of every flaw.</p>',
 cards=('💡 Kandarpa','A name of Kāma, the god of love, who carries a sugarcane bow and flower arrows.','💡 Rāmānuja','The 11th–12th-century teacher of Viśiṣṭādvaita whose tradition this hymn belongs to.'),
 inner='The deepest beauty is goodness that shines out.',
 talk=('More handsome than the god of love?','In the poet\'s words, Kāma\'s pride melts away. And He\'s also a mine of every good quality.'),
 key='Beauty that humbles Kāma, <b>goodness without a flaw</b>.'),
D(n='24',lines=L(['mīnākṛte kamaṭha kola','nṛsiṃha varṇin'],['svāmin paraśvathatapodhana','rāmacandra |'],['śeṣāṃśarāma yadunandana','kalkirūpa'],None,24),theme='THE TEN AVATĀRAS',
 svg=svg('Ten small icons in two rows: fish, tortoise, boar, man-lion, dwarf, axe, bow, plough, flute, horse',
  ''.join(f'<g transform="translate({28+41*(k%5)} {50+64*(k//5)})"><circle r="18" fill="#fff" stroke="#111" stroke-width="2"/><text y="5" text-anchor="middle" font-size="16">{e}</text></g>'+f'<text x="{28+41*(k%5)}" y="{82+64*(k//5)}" text-anchor="middle" {F} font-size="6">{t}</text>' for k,(e,t) in enumerate([('🐟','MATSYA'),('🐢','KŪRMA'),('🐗','VARĀHA'),('🦁','NṚSIṂHA'),('☂️','VĀMANA'),('🪓','PARAŚURĀMA'),('🏹','RĀMA'),('🌾','BALARĀMA'),('🪈','KṚṢṆA'),('🐎','KALKI')])),B),
 mean='O You who took the form of a fish, a tortoise, a boar, the man-lion and the young celibate; O Lord who was the ascetic with the axe and Rāmacandra; O Balarāma, part of Śeṣa; O joy of the Yadus; O You who take the form of Kalki. O Lord of Veṅkaṭācala, good morning!',
 plain='Fish, tortoise, boar, man-lion, dwarf, Paraśurāma, Rāma, Balarāma, Kṛṣṇa and Kalki: all ten avatāras are You. Good morning, Lord!',
 words=[('mīna · kamaṭha','<b>fish</b> · <b>tortoise</b>'),('kola · nṛsiṃha','<b>boar</b> · <b>man-lion</b>'),('varṇin','<b>young celibate</b>: Vāmana'),('paraśvatha-tapodhana','<b>axe-bearing ascetic</b>: Paraśurāma'),('śeṣa-aṃśa-rāma','<b>Rāma born of Śeṣa</b>: Balarāma'),('yadu-nandana','<b>joy of the Yadus</b>: Kṛṣṇa')],
 deep='<p><b>The daśāvatāra.</b> All ten avatāras in one verse: Matsya, Kūrma, Varāha, Narasiṃha, Vāmana, Paraśurāma, Rāma, Balarāma, Kṛṣṇa and Kalki.</p><p><b>Lists vary.</b> This list counts Balarāma and Kṛṣṇa separately; other lists (such as Jayadeva\'s Gītagovinda) include the Buddha in place of one of them. The Suprabhātam follows a common South Indian list.</p><p><b>Back to verse 1.</b> The hymn began with Rāma; here He reappears among His fellow avatāras, all one Lord, now standing on the Seven Hills.</p>',
 cards=('💡 Avatāra','"Descent": the Lord\'s coming into the world to protect dharma (Gītā 4.7–8).','💡 Kalki','The avatāra yet to come, at the end of the Kali age.'),
 inner='The Lord who came again and again is the one standing before you now.',
 talk=('Isn\'t the Buddha one of the ten?','In some lists. This hymn counts Balarāma and Kṛṣṇa separately. Lists differ by region and tradition.'),
 key='Fish to Kalki: <b>all ten avatāras wake on the Seven Hills</b>.',
 note='Lists of the ten avatāras differ between traditions.'),
D(n='25',lines=[['elālavaṅgaghanasāra-','sugandhitīrthaṃ'],['divyaṃ viyatsariti','hemaghaṭeṣu pūrṇam |'],['dhṛtvādya vaidika-','śikhāmaṇayaḥ prahṛṣṭāḥ'],['tiṣṭhanti veṅkaṭapate','tava suprabhātam ‖25‖']],theme='SCENTED WATER FOR THE BATH',
 svg=svg('Vedic priests holding golden pots of scented water, with cardamom, cloves and camphor, beside a waterfall',
  '<path d="M16 20 q4 50 0 110" stroke="#4aa3df" stroke-width="7" fill="none"/>'+''.join(f'<g transform="translate({60+48*k} 0)">'+person(0,136,'#fff','#f2c79b',.6)+f'<path d="M14 84 q12 -6 24 0 l-4 20 h-16z" fill="#ffd60a" stroke="#111" stroke-width="2"/></g>' for k in range(3))+lab(120,26,'ELĀ · LAVAṄGA · KARPŪRA',9),B),
 mean='Holding divine holy water from the heavenly river in golden pots, fragrant with cardamom, cloves and camphor, the crest-jewels of Vedic learning stand joyfully today. O Lord of Veṅkaṭa, good morning!',
 plain='The great Vedic scholars stand happily with golden pots of sacred water, scented with cardamom, clove and camphor, ready for You. Good morning, Lord!',
 words=[('elā · lavaṅga','<b>cardamom</b> · <b>clove</b>'),('ghanasāra','<b>camphor</b>'),('tīrtham','<b>holy water</b>'),('viyat-sarit','the <b>sky-river</b>'),('hema-ghaṭa','<b>golden pots</b>'),('vaidika-śikhāmaṇayaḥ','<b>crest-jewels of the Vedas</b>: great scholars')],
 deep='<p><b>Ready for the bath.</b> After waking, the Lord is bathed and worshipped. The priests already stand with scented water in golden pots.</p><p><b>Sky-river again.</b> As in verse 5, <i>viyat-sarit</i>, "sky-river", is both the heavenly Gaṅgā and the Ākāśa Gaṅgā near Tirumala, whose water is used for the Lord\'s service.</p><p><b>A change of refrain.</b> Verses 25 and 26 end differently: "tiṣṭhanti veṅkaṭapate" ("they stand, O Lord of Veṅkaṭa") and "dhāmāśrayanti" ("they come to Your abode"), before the familiar refrain returns.</p>',
 cards=('💡 Tīrtha','Holy water; also a sacred bathing place or pilgrimage spot.','💡 Ghanasāra','Camphor: used in temple water and in the āratī flame.'),
 inner='Prepare your offering with care, and offer it with joy.',
 talk=('Cardamom and camphor in the water?','Fragrant water for the Lord\'s bath. The scholars are standing ready, delighted to serve.'),
 key='Golden pots of scented water: <b>ready for the Lord\'s bath</b>.',
 note='Some texts read sugandha-tīrthaṃ for sugandhi-tīrthaṃ.'),
D(n='26',lines=[['bhāsvānudeti','vikacāni saroruhāṇi'],['sampūrayanti ninadaiḥ','kakubho vihaṅgāḥ |'],['śrīvaiṣṇavāḥ satatam','arthitamaṅgalāste'],['dhāmāśrayanti tava','veṅkaṭa suprabhātam ‖26‖']],theme='THE SUN IS UP',
 svg=svg('The sun rising, lotuses fully open, birds flying across the sky, and devotees walking toward the temple',SUN(40,50,22)+'<rect x="0" y="120" width="220" height="40" fill="#9fd3f0"/>'+''.join(f'<path d="M{x} 124 q-14 -20 0 -30 q14 10 0 30z" fill="#f08aa6" stroke="#111"/>' for x in (30,60))+''.join(f'<path d="M{x} {y} q6 -6 12 0 q6 -6 12 0" fill="none" stroke="#111" stroke-width="2"/>' for x,y in [(90,40),(120,30),(150,46)])+TEMPLE(190,110,.8)+crowd(['#ff8c1a','#fff'],110,24,126,.4),B),
 mean='The sun is rising; the lotuses are in full bloom; birds fill the directions with their calls. The Śrīvaiṣṇavas, always praying for blessings, come to Your abode. O Veṅkaṭa, good morning!',
 plain='The sun is up, the lotuses are open, the birds are singing everywhere, and the devotees are arriving at Your temple. Good morning, Lord!',
 words=[('bhāsvān udeti','<b>the sun rises</b>'),('vikacāni','<b>fully opened</b>'),('saroruha','<b>lotuses</b>'),('kakubhaḥ','the <b>directions</b>'),('vihaṅgāḥ','<b>birds</b>'),('dhāma āśrayanti','<b>come to Your abode</b>')],
 deep='<p><b>Dawn has come.</b> In verse 7 the lotuses were half-open; now they are fully open (<i>vikacāni</i>). The sun is up: the waking is complete.</p><p><b>Śrīvaiṣṇavas.</b> The devotees of Śrī and Viṣṇu, the tradition of Rāmānuja and of the poet himself, arrive at the temple, always asking for blessings, for the world as much as for themselves.</p><p><b>Time moves through the hymn.</b> From the first light of verse 1 to full sunrise here, the hymn follows a real morning.</p>',
 cards=('💡 Śrīvaiṣṇava','Followers of the Lakṣmī-Nārāyaṇa tradition taught by Rāmānuja.','💡 Maṅgala','Auspiciousness, blessing: the word gives its name to the last section.'),
 inner='When the sun is up, go to the Lord. Begin the day where it should begin.',
 talk=('Is the sun actually up now?','Yes! Verse 7 had half-open lotuses; now they\'re fully open. The hymn follows a real sunrise.'),
 key='The sun is up, the lotuses open: <b>the devotees arrive</b>.'),
D(n='27',lines=L(['brahmādayassuravarās','samaharṣayaste'],['santassanandanamukhās','tvatha yogivaryāḥ |'],['dhāmāntike tava hi','maṅgalavastuhastāḥ'],None,27),theme='WAITING WITH AUSPICIOUS GIFTS',
 svg=svg('Brahma, sages and yogis standing near the temple holding auspicious objects: a mirror, a lamp, a flower garland and a pot',DOOR+''.join(f'<g transform="translate({26+30*k} 0)">'+person(0,136,c,'#f2c79b',.5)+f'<text x="12" y="92" font-size="14">{e}</text></g>' for k,(c,e) in enumerate([('#e63946','🪞'),('#fff','🪔'),('#ff8c1a','💐'),('#2a9d6f','🏺')]))+lab(70,30,'MAṄGALA VASTU',10),B),
 mean='Brahmā and the other great gods, the great sages, holy ones led by Sanandana, and the best of yogis stand close to Your abode, with auspicious objects in their hands. O Lord of Veṅkaṭācala, good morning!',
 plain='Brahmā, the gods, the great sages and yogis stand near Your shrine holding auspicious offerings. Good morning, Lord!',
 words=[('brahma-ādayaḥ','<b>Brahmā and others</b>'),('sura-varāḥ','<b>the best of gods</b>'),('maharṣayaḥ','<b>great sages</b>'),('sanandana-mukhāḥ','<b>led by Sanandana</b>'),('yogi-varyāḥ','<b>the best of yogis</b>'),('maṅgala-vastu-hastāḥ','<b>with auspicious objects in hand</b>')],
 deep='<p><b>Auspicious things.</b> The first things the Lord should see on waking are auspicious: a mirror, a lamp, flowers, a full pot, a cow. The gods and sages hold these ready.</p><p><b>Sanandana.</b> One of the four child-sages (Sanaka, Sanandana, Sanātana, Sanatkumāra), born of Brahmā\'s mind and forever young.</p><p><b>Everyone is here.</b> Gods, sages, yogis, planets, guardians, animals, devotees: by verse 27 the whole universe is assembled at the door.</p>',
 cards=('💡 Sanaka brothers','Four eternal child-sages, sons of Brahmā\'s mind, devoted to Viṣṇu.','💡 Maṅgala-vastu','Auspicious objects: lamp, mirror, flowers, full pot, and so on.'),
 inner='Let the first thing you see each morning be something good.',
 talk=('Why hold up a mirror?','Auspicious objects are the first things shown on waking: a mirror, a lamp, flowers. The whole court has brought them.'),
 key='The whole court waits <b>with auspicious gifts</b>.'),
D(n='28',lines=L(['lakṣmīnivāsa','niravadyaguṇaikasindho'],['saṃsārasāgara-','samuttaraṇaikaseto |'],['vedāntavedyanija-','vaibhava bhaktabhogya'],None,28),theme='THE BRIDGE ACROSS THE OCEAN',
 svg=svg('A bridge across a stormy ocean leading to a hill with a temple and a shining figure',
  ''.join(f'<path d="M{20*k} 120 q10 -8 20 0" fill="none" stroke="#1d6fb8" stroke-width="3"/>' for k in range(11))+'<rect x="0" y="122" width="220" height="38" fill="#4aa3df"/><path d="M10 110 q100 -50 180 0" fill="none" stroke="#7a5a3a" stroke-width="6"/>'+TEMPLE(190,104,.7)+person(40,112,'#ff8c1a','#f2c79b',.4)+lab(110,30,'SAMSĀRA-SĀGARA',10),B),
 mean='O home of Lakṣmī, the one ocean of flawless virtues, the one bridge for crossing the ocean of worldly life, whose glory is known through the Vedānta, who is to be enjoyed by His devotees. O Lord of Veṅkaṭācala, good morning!',
 plain='Home of Lakṣmī, full of perfect virtues, the only bridge across the sea of birth and death, known through the Upaniṣads, the joy of devotees: good morning, Lord!',
 words=[('lakṣmī-nivāsa','<b>home of Lakṣmī</b>'),('niravadya-guṇa','<b>flawless virtues</b>'),('saṃsāra-sāgara','the <b>ocean of worldly life</b>'),('eka-seto','<b>O the one bridge</b>'),('vedānta-vedya','<b>known through Vedānta</b>'),('bhakta-bhogya','<b>enjoyed by devotees</b>')],
 deep='<p><b>The last address.</b> The final verse of praise gathers the whole theology: the Lord is Lakṣmī\'s home, flawless, the way out of saṃsāra, known through the Upaniṣads, and sweet to His devotees.</p><p><b>The bridge.</b> Rāma built a bridge to Laṅkā; the Lord Himself is the bridge across the ocean of saṃsāra.</p><p><b>Known and enjoyed.</b> <i>Vedānta-vedya</i>: the philosophers know Him through scripture. <i>Bhakta-bhogya</i>: the devotees enjoy Him through love. Both are true.</p>',
 cards=('💡 Saṃsāra','The cycle of birth, death and rebirth.','💡 Vedānta','"The end of the Vedas": the Upaniṣads and the philosophies built on them.'),
 inner='The scholar knows Him; the devotee tastes Him. Be both if you can.',
 talk=('A bridge across an ocean?','The ocean of birth and death. The Lord is the only bridge across it, like Rāma\'s bridge to Laṅkā.'),
 key='Lakṣmī\'s home: <b>the one bridge across the sea of saṃsāra</b>.'),
D(n='29',lines=[['itthaṃ vṛṣācalapater','iha suprabhātaṃ'],['ye mānavāḥ pratidinaṃ','paṭhituṃ pravṛttāḥ |'],['teṣāṃ prabhātasamaye','smṛtiraṅgabhājāṃ'],['prajñāṃ parārthasulabhāṃ','paramāṃ prasūte ‖29‖']],theme='THE BLESSING OF RECITING IT',
 svg=svg('A person at home at dawn reciting the Suprabhatam beside a lamp, with a glow of wisdom around their head',SUN(180,40,16)+person(90,134,'#ff8c1a','#f2c79b',.8)+'<circle cx="90" cy="74" r="26" fill="none" stroke="#ffd60a" stroke-width="4" stroke-dasharray="4 4"/><g transform="translate(150 140)" stroke="#111" stroke-width="2"><path d="M-14 0 h28 l-4 8 h-20z" fill="#e0a800"/><path d="M0 0 q-8 -16 0 -24 q8 8 0 24z" fill="#ff8c1a"/></g>'+lab(90,24,'PHALAŚRUTI',11),B),
 mean='Those who take up reciting this Suprabhātam of the Lord of Vṛṣācala here every day: for them, remembering it at dawn brings forth the highest wisdom, which makes the supreme goal easy to reach.',
 plain='Whoever recites this morning hymn to the Lord of the hills every day will gain the highest wisdom, and with it the highest goal comes easily.',
 words=[('ittham','<b>thus</b>, this'),('vṛṣācala-pati','<b>Lord of Vṛṣācala</b>'),('pratidinam','<b>every day</b>'),('prabhāta-samaye','<b>at dawn</b>'),('prajñām paramām','<b>the highest wisdom</b>'),('para-artha-sulabhām','<b>making the highest goal easy</b>')],
 deep='<p><b>The phalaśruti.</b> Many hymns end with a verse stating the "fruit of hearing" (<i>phalaśruti</i>). Here the fruit is not wealth or long life but <b>prajñā</b>, wisdom, the kind that leads to the highest goal.</p><p><b>No refrain.</b> This is the only verse without "tava suprabhātam": the waking is done; now the poet turns to us.</p><p><b>Every day, at dawn.</b> The condition is simple: recite it daily, at dawn. That is exactly what millions of homes do.</p>',
 cards=('💡 Phalaśruti','"Hearing of the fruit": the closing verse listing a hymn\'s benefits.','💡 Prajñā','Wisdom, insight: deeper than knowledge.'),
 inner='Wake the Lord each morning, and He will wake wisdom in you.',
 talk=('What do we get for reciting it?','Not riches: wisdom, the kind that makes the highest goal easy. Every morning, at dawn.'),
 key='Recite it daily at dawn: <b>it gives the highest wisdom</b>.'),
]
